package pose

import (
 "encoding/json"
 "os"
 "os/exec"
 "path/filepath"
 "strings"
 "testing"
 "time"
)

// Diagnostic probes: PASS means the observation was reproduced, not that the gate is sound.
func TestB38R4NullEvidenceKind(t *testing.T) {
 r:=newReleaseRepo(t,"v1.0.0")
 bare:=ReleasePolicy{SchemaVersion:1}
 r.manifest=NewReleaseManifest(r.version,"",r.manifest.PreparedAt,r.manifest.Fragments,bare,ChangelogPolicy{},map[string]string{"source":EngineVersionFile,"kind":"","value":r.version})
 raw:=strings.Replace(string(CanonicalJSON(r.manifest)),`"kind": ""`,`"kind": null`,1)
 _,issues:=ValidateReleaseManifestBytes([]byte(raw),r.version)
 t.Logf("null kind issues=%v",issues)
 if len(issues)!=0 {t.Fatal("observation changed")}
}

func TestB38R4PreparedStatus(t *testing.T) {
 for _,victim:=range []string{".pose/changelogs/v1.0.0.md",".pose/changelogs/v1.0.0/alpha.md","VERSION"} {
  r:=newReleaseRepo(t,"v1.0.0");os.Remove(filepath.Join(r.root,victim))
  s,e:=(Store{Root:r.root}).GetReleaseStatus(r.version)
  if e!=nil {t.Fatal(e)}
  t.Logf("lost=%s state=%s sound=%t gaps=%v",victim,s.Releases[0].State,s.Releases[0].Sound(),s.Releases[0].Gaps)
  if !s.Releases[0].Sound(){t.Fatal("observation changed")}
 }
}

func TestB38R4UnsoundVerifiedObligation(t *testing.T) {
 r:=tagged(t,newReleaseRepo(t,"v1.0.0"))
 e:=ReleaseEvidence{SchemaVersion:1,Provider:"github",Repository:"o/r",Version:r.version,Tag:r.version,Commit:r.headCommit(t,r.version)}
 taggedEv:=NewReleaseEvent(r.version,"tagged",e,time.Now())
 pub:=NewReleaseEvent(r.version,"published",e,time.Now())
 e.Publication=pub.EvidenceDigest
 verified:=NewReleaseEvent(r.version,"verified",e,time.Now())
 lines:=[]string{}
 for _,v:=range []ReleaseEvent{taggedEv,pub,verified}{raw,_:=json.Marshal(v);lines=append(lines,string(raw))}
 relWrite(t,r.root,".pose/releases/v1.0.0/events.jsonl",strings.Join(lines,"\n")+"\n")
 os.Remove(filepath.Join(r.root,".pose/changelogs/v1.0.0.md"))
 s,err:=(Store{Root:r.root}).GetReleaseStatus("");if err!=nil{t.Fatal(err)}
 obs,err:=(Store{Root:r.root}).releaseQueueObligations("proj.test");if err!=nil{t.Fatal(err)}
 t.Logf("state=%s sound=%t gaps=%v obligations=%v",s.Releases[0].State,s.Releases[0].Sound(),s.Releases[0].Gaps,obs)
 if s.Releases[0].Sound()||len(obs)!=0{t.Fatal("observation changed")}
}

func TestB38R4ArchiveDifferentCut(t *testing.T) {
 r:=tagged(t,newReleaseRepo(t,"v1.0.0"))
 r.body=strings.ReplaceAll(r.body,"alpha","beta")
 f:=ReleaseFragment{Spec:"beta",Category:"fixed",Body:"Fixes beta.",Path:"alpha.md",Digest:ReleaseDigest(r.body)}
 r.manifest=NewReleaseManifest(r.version,"",r.manifest.PreparedAt,[]ReleaseFragment{f},fixtureReleasePolicy(),ChangelogPolicy{},r.manifest.VersionEvidence)
 r.notes=RenderReleaseNotes(r.version,r.manifest.Fragments,ChangelogPolicy{})
 r.writeAll(t);r.commit(t,"replace the cut")
 a:=LoadArchivedFragments(r.root)
 witness,note,ok:=newArchivalLedger(a,func(string)bool{return true}).resolve("beta",pendingFragmentDir+"alpha.md","")
 s,err:=(Store{Root:r.root}).GetReleaseStatus(r.version);if err!=nil{t.Fatal(err)}
 t.Logf("witness=%+v ok=%t note=%s status_sound=%t status_gaps=%v",witness,ok,note,s.Releases[0].Sound(),s.Releases[0].Gaps)
 if !ok||!witness.Intact||s.Releases[0].Sound(){t.Fatal("observation changed")}
}

func TestB38R4ReadmeInArchive(t *testing.T){
 r:=newReleaseRepo(t,"v1.0.0");relWrite(t,r.root,".pose/changelogs/v1.0.0/README.md","archive guide\n")
 fs,e:=LoadReleaseFragments(filepath.Join(r.root,".pose/changelogs/v1.0.0"),ChangelogPolicy{});if e!=nil{t.Fatal(e)}
 snap:=snapshotOf(t,tagged(t,r))
 t.Logf("loaded_fragments=%d snapshot_intact=%t gaps=%v",len(fs),snap.Intact(),snap.Gaps)
 if snap.Intact(){t.Fatal("observation changed")}
}

func TestB38R4ChangelogFuturePolicy(t *testing.T){
 r:=newReleaseRepo(t,"v1.0.0");relWrite(t,r.root,".pose/policy/changelog.json",`{"schema_version":999,"categories":["fixed"]}`)
 snap:=snapshotOf(t,tagged(t,r));t.Logf("intact=%t gaps=%v limits=%v",snap.Intact(),snap.Gaps,snap.Limits)
 if !snap.Intact(){t.Fatal("observation changed")}
}

func TestB38R4DanglingReleaseRoot(t *testing.T){
 r:=newReleaseRepo(t,"v1.0.0");os.Rename(filepath.Join(r.root,".pose/releases"),filepath.Join(r.root,".pose/releases.saved"))
 os.Symlink("missing",filepath.Join(r.root,".pose/releases"))
 s,e:=(Store{Root:r.root}).GetReleaseStatus("")
 t.Logf("status=%+v err=%v",s,e)
 if e!=nil||len(s.Releases)!=0{t.Fatal("observation changed")}
}

func TestB38R4GitObjectLossIsAbsence(t *testing.T){
 r:=newReleaseRepo(t,"v1.0.0")
 relWrite(t,r.root,".pose/policy/changelog.json",`{"schema_version":1,"categories":["fixed"]}`)
 r=tagged(t,r)
 real,e:=exec.LookPath("git");if e!=nil{t.Fatal(e)}
 shim:=t.TempDir()
 script:="#!/bin/sh\ncase \"$*\" in\n*\"cat-file blob\"*\":.pose/policy/changelog.json\"*) echo 'fatal: Not a valid object name unreadable-blob' >&2; exit 128;;\nesac\nexec "+real+" \"$@\"\n"
 if e:=os.WriteFile(filepath.Join(shim,"git"),[]byte(script),0755);e!=nil{t.Fatal(e)}
 t.Setenv("PATH",shim+string(os.PathListSeparator)+os.Getenv("PATH"))
 snap,e:=ReadReleaseSnapshot(r.root,r.version)
 t.Logf("unreadable_changelog_blob intact=%t issues=%v gaps=%v limits=%v err=%v",snap.Intact(),snap.Issues,snap.Gaps,snap.Limits,e)
 if e!=nil||!snap.Intact(){t.Fatal("observation changed")}
}

func TestB38R4VersionSourceSymlink(t *testing.T){
 r:=newReleaseRepo(t,"v1.0.0")
 os.Remove(filepath.Join(r.root,"VERSION"))
 os.Symlink("1.0.0",filepath.Join(r.root,"VERSION"))
 relWrite(t,r.root,"1.0.0","9.9.9\n")
 actual,e:=ReadReleaseVersionSource(r.root,*fixtureReleasePolicy().VersionSource)
 if e!=nil{t.Fatal(e)}
 snap:=snapshotOf(t,tagged(t,r))
 s,e:=(Store{Root:r.root}).GetReleaseStatus(r.version)
 if e!=nil{t.Fatal(e)}
 t.Logf("actual_source=%s snapshot_intact=%t gaps=%v limits=%v status_sound=%t",actual,snap.Intact(),snap.Gaps,snap.Limits,s.Releases[0].Sound())
 if actual!="v9.9.9"||!snap.Intact()||!s.Releases[0].Sound(){t.Fatal("observation changed")}
}

func TestB38R4RealLostGitObjects(t *testing.T){
 for _,victim:=range []string{".pose/policy/changelog.json",".pose/policy"} {
  r:=newReleaseRepo(t,"v1.0.0")
  relWrite(t,r.root,".pose/policy/changelog.json",`{"schema_version":1,"categories":["fixed"]}`)
  relWrite(t,r.root,".pose/release-policy.json",string(CanonicalJSON(fixtureReleasePolicy())))
  r=tagged(t,r)
  id:=relGit(t,r.root,"rev-parse","HEAD:"+victim)
  os.Remove(filepath.Join(r.root,".git/objects",id[:2],id[2:]))
  snap,e:=ReadReleaseSnapshot(r.root,r.version)
  t.Logf("lost_object=%s intact=%t gaps=%v err=%v",victim,snap.Intact(),snap.Gaps,e)
 }
}

func TestB38R4MultilineFragmentIsRefused(t *testing.T){
 r:=newReleaseRepo(t,"v1.0.0")
 r.body="---\nspec: alpha\ncategory: fixed\nbreaking: false\n---\n\nFirst line.\nSecond line.\n"
 relWrite(t,r.root,".pose/changelogs/v1.0.0/alpha.md",r.body)
 fs,e:=LoadReleaseFragments(filepath.Join(r.root,".pose/changelogs/v1.0.0"),ChangelogPolicy{});if e!=nil{t.Fatal(e)}
 r.manifest=NewReleaseManifest(r.version,"",r.manifest.PreparedAt,fs,fixtureReleasePolicy(),ChangelogPolicy{},r.manifest.VersionEvidence)
 raw:=CanonicalJSON(r.manifest)
 var conventional ReleaseManifest
 je:=json.Unmarshal(raw,&conventional)
 _,issues:=ValidateReleaseManifestBytes(raw,r.version)
 t.Logf("valid_json_error=%v fragment_body=%q issues=%v",je,fs[0].Body,issues)
 if je!=nil||len(issues)==0{t.Fatal("observation changed")}
}

func TestB38R4HistoricalManifests(t *testing.T){
 root:=os.Getenv("POSE_B38_REVIEW_ROOT");if root==""{t.Skip("repository inventory was not requested")}
 entries,e:=os.ReadDir(filepath.Join(root,".pose/releases"));if e!=nil{t.Fatal(e)}
 valid,invalid:=0,0
 for _,entry:=range entries {
  if !entry.IsDir()||ValidateReleaseVersion(entry.Name())!=nil{continue}
  raw,e:=os.ReadFile(filepath.Join(root,".pose/releases",entry.Name(),"manifest.json"));if e!=nil{t.Fatal(e)}
  _,issues:=ValidateReleaseManifestBytes(raw,entry.Name())
  if len(issues)==0{valid++}else{invalid++;t.Logf("version=%s issues=%v",entry.Name(),issues)}
 }
 t.Logf("historical_inventory valid=%d invalid=%d",valid,invalid)
}

func TestB38R4InvalidCutoffHidesTags(t *testing.T){
 r:=newReleaseRepo(t,"v1.0.0")
 relGit(t,r.root,"rm","-r","-q",".pose/releases",".pose/changelogs")
 relGit(t,r.root,"commit","-qm","no release snapshot")
 relGit(t,r.root,"tag",r.version)
 p:=fixtureReleasePolicy();p.AdoptedAt="2026-08-03";p.Provider="github";p.Repository="o/r";p.LegacyCutoff="not-a-version"
 relWrite(t,r.root,".pose/policy/release.json",string(CanonicalJSON(p)))
 s,e:=(Store{Root:r.root}).GetReleaseStatus("")
 t.Logf("policy_validation=%v cutoff_comparison=%d status=%+v err=%v",ValidateReleasePolicy(p),CompareReleasePrecedence(p.LegacyCutoff,r.version),s,e)
 if ValidateReleasePolicy(p)!=nil||e!=nil||len(s.Releases)!=0{t.Fatal("observation changed")}
 p.LegacyCutoff=""
 relWrite(t,r.root,".pose/policy/release.json",string(CanonicalJSON(p)))
 s,e=(Store{Root:r.root}).GetReleaseStatus("")
 t.Logf("control_without_cutoff=%+v err=%v",s,e)
 if e!=nil||len(s.Releases)!=1||len(s.Releases[0].Gaps)==0{t.Fatal("control failed")}
}

