package cli

import (
 "bytes"
 "os"
 "path/filepath"
 "strings"
 "testing"
 posemodel "github.com/harne8/pose-mcp/internal/pose"
)

func TestB38R4PreparedNotesProjection(t *testing.T){
 root:=cliReleaseRepo(t)
 m,e:=posemodel.LoadReleaseManifest(root,"v1.0.0");if e!=nil{t.Fatal(e)}
 m.NotesDigest=posemodel.ReleaseDigest("# Unrelated notes\n")
 writeCloseoutCLIFile(t,root,".pose/changelogs/v1.0.0.md","# Unrelated notes\n")
 writeCloseoutCLIFile(t,root,".pose/releases/v1.0.0/manifest.json",string(posemodel.CanonicalJSON(m)))
 gaps,_:=checkRelease(root,"v1.0.0")
 var out,errs bytes.Buffer
 code:=cmdReleaseNotesSnapshot(root,[]string{"--version","v1.0.0"},&out,&errs)
 t.Logf("prepared_gaps=%v notes_code=%d notes=%q",gaps,code,out.String())
 if len(gaps)!=0||code!=0{t.Fatal("observation changed")}
 relGitCLI(t,root,"add","-A");relGitCLI(t,root,"commit","-qm","changed notes");relGitCLI(t,root,"tag","v1.0.0")
 gaps,_=checkRelease(root,"v1.0.0");out.Reset();errs.Reset()
 code=cmdReleaseNotesSnapshot(root,[]string{"--version","v1.0.0"},&out,&errs)
 t.Logf("tagged_gaps=%v notes_code=%d notes=%q",gaps,code,out.String())
 if len(gaps)==0||code!=0{t.Fatal("observation changed")}
}

func TestB38R4PreparedLostArchiveNotes(t *testing.T){
 root:=cliReleaseRepo(t)
 os.Remove(filepath.Join(root,".pose/changelogs/v1.0.0/alpha.md"))
 os.Remove(filepath.Join(root,".pose/changelogs/v1.0.0.md"))
 gaps,_:=checkRelease(root,"v1.0.0")
 s,e:=(posemodel.Store{Root:root}).GetReleaseStatus("")
 t.Logf("check_gaps=%v status=%+v err=%v",gaps,s,e)
 if len(gaps)==0||e!=nil||!s.Releases[0].Sound(){t.Fatal("observation changed")}
}

func TestB38R4PolicyFallbackOnLoss(t *testing.T){
 root:=cliReleaseRepo(t)
 old,err:=os.ReadFile(filepath.Join(root,".pose/policy/release.json"));if err!=nil{t.Fatal(err)}
 writeCloseoutCLIFile(t,root,".pose/release-policy.json",string(old))
 os.Remove(filepath.Join(root,".pose/policy/release.json"));os.Mkdir(filepath.Join(root,".pose/policy/release.json"),0755)
 writeCloseoutCLIFile(t,root,".pose/policy/release.json/child","not a policy")
 gaps,_:=checkRelease(root,"v1.0.0")
 relGitCLI(t,root,"add","-A");relGitCLI(t,root,"commit","-qm","policy fallback");relGitCLI(t,root,"tag","v1.0.0")
 snap,e:=posemodel.ReadReleaseSnapshot(root,"v1.0.0")
 t.Logf("prepared_gaps=%v snapshot_intact=%t snapshot_gaps=%v err=%v",gaps,snap.Intact(),snap.Gaps,e)
 if len(gaps)!=0||e!=nil||snap.Intact(){t.Fatal("observation changed")}
}

func TestB38R4PrepareNormalizesSource(t *testing.T){
 root:=t.TempDir()
 writeCloseoutCLIFile(t,root,"VERSION","1.0.0\n")
 writeCloseoutCLIFile(t,root,".pose/policy/release.json",`{"schema_version":1,"adopted_at":"2026-08-03","provider":"github","repository":"o/r","allow_empty":true,"version_source":{"path":"./VERSION","kind":"text"}}`)
 var out,errs bytes.Buffer
 code:=cmdReleasePrepare(root,[]string{"--version","v1.0.0","--apply"},&out,&errs)
 m,e:=posemodel.LoadReleaseManifest(root,"v1.0.0")
 t.Logf("prepare_code=%d out=%s stderr=%s own_loader_error=%v source=%s",code,out.String(),errs.String(),e,m.VersionEvidence["source"])
 if code!=0||e!=nil||m.VersionEvidence["source"]!="VERSION" {t.Fatal("control failed")}
}

func TestB38R4CleanSourceAlias(t *testing.T){
 root:=cliReleaseRepo(t)
 p,_:=posemodel.LoadReleasePolicy(root);p.VersionSource.Path="./VERSION"
 m,_:=posemodel.LoadReleaseManifest(root,"v1.0.0")
 m2:=posemodel.NewReleaseManifest(m.Version,m.PreviousVersion,m.PreparedAt,m.Fragments,p,posemodel.ChangelogPolicy{},map[string]string{"source":"./VERSION","kind":"text","value":m.Version})
 writeCloseoutCLIFile(t,root,".pose/policy/release.json",string(posemodel.CanonicalJSON(p)))
 writeCloseoutCLIFile(t,root,".pose/releases/v1.0.0/manifest.json",string(posemodel.CanonicalJSON(m2)))
 _,e:=posemodel.LoadReleaseManifest(root,"v1.0.0")
 t.Logf("policy_validate=%v manifest_error=%v",p.VersionSource.Validate(),e)
 if e==nil||!strings.Contains(e.Error(),"clean project-relative path"){t.Fatal("observation changed")}
}

func TestB38R4LostTagVsRecordedState(t *testing.T){
 root:=cliReleaseRepo(t);relGitCLI(t,root,"tag","v1.0.0")
 head:=strings.TrimSpace(gitOut(t,root,"rev-parse","HEAD"))
 writeCloseoutCLIFile(t,root,"evidence.json",`{"schema_version":1,"provider":"github","repository":"o/r","version":"v1.0.0","tag":"v1.0.0","commit":"`+head+`"}`)
 var out,errs bytes.Buffer
 code:=cmdReleaseRecord(root,[]string{"--version","v1.0.0","--event","tagged","--evidence","evidence.json"},&out,&errs)
 if code!=0{t.Fatalf("control record: %d %s",code,errs.String())}
 relGitCLI(t,root,"tag","-d","v1.0.0")
 gaps,_:=checkRelease(root,"v1.0.0")
 s,e:=(posemodel.Store{Root:root}).GetReleaseStatus("v1.0.0");if e!=nil{t.Fatal(e)}
 out.Reset();errs.Reset();code=cmdReleaseCheck(root,[]string{"--version","v1.0.0","--strict","--json"},&out,&errs)
 t.Logf("recorded_state=%s sound=%t status_gaps=%v check_gaps=%v strict_code=%d result=%s",s.Releases[0].State,s.Releases[0].Sound(),s.Releases[0].Gaps,gaps,code,out.String())
 if s.Releases[0].Sound()||len(gaps)!=0||code!=0{t.Fatal("observation changed")}
}

func TestB38R4HumanStatusLimits(t *testing.T){
 root:=cliReleaseRepoKind(t,"engine");relGitCLI(t,root,"tag","v1.0.0")
 var out,errs bytes.Buffer
 code:=cmdReleaseStatus(root,nil,&out,&errs)
 s,e:=(posemodel.Store{Root:root}).GetReleaseStatus("");if e!=nil{t.Fatal(e)}
 t.Logf("code=%d human=%q limits=%v",code,out.String(),s.Releases[0].Snapshot.Limits)
 if code!=0||len(s.Releases[0].Snapshot.Limits)==0||strings.Contains(out.String(),"re-read"){t.Fatal("observation changed")}
}

func TestB38R4InvalidCutoffSkipsChecker(t *testing.T){
 root:=cliReleaseRepo(t)
 relGitCLI(t,root,"rm","-r","-q",".pose/releases",".pose/changelogs")
 relGitCLI(t,root,"commit","-qm","without snapshot");relGitCLI(t,root,"tag","v1.0.0")
 p:=cliFixturePolicy("text");p.AdoptedAt="2026-08-03";p.Provider="github";p.Repository="o/r";p.LegacyCutoff="not-a-version"
 writeCloseoutCLIFile(t,root,".pose/policy/release.json",string(posemodel.CanonicalJSON(p)))
 var out bytes.Buffer
 c:=nativeChecker{root:root,mode:"strict",stdout:&out};appendReleasePolicyChecks(&c)
 t.Logf("invalid_cutoff errors=%d warnings=%d output=%q",c.errors,c.warnings,out.String())
 if c.errors!=0{t.Fatal("observation changed")}
 p.LegacyCutoff="";writeCloseoutCLIFile(t,root,".pose/policy/release.json",string(posemodel.CanonicalJSON(p)))
 c=nativeChecker{root:root,mode:"strict",stdout:&out};appendReleasePolicyChecks(&c)
 t.Logf("without_cutoff errors=%d output=%q",c.errors,out.String())
 if c.errors==0{t.Fatal("control failed")}
}
